		//Refresh the list of valid sys_ids

	var list_sys_id = [];
	if (gs.getSession().getClientData('list_sys_id').length < 1){
		var gr = new GlideRecordSecure('x_hccc_hoc_ohs_investigation_case');
		gr.query();
		while (gr.next()){
			list_sys_id.push(gr.getValue('sys_id'));
		}
		gs.getSession().putClientData('list_sys_id', JSON.stringify(list_sys_id));
	}
	else
	{
		list_sys_id = JSON.parse(getSession().getClientData('list_sys_id'));
	}

		/*gs.info("AMP TEST")
